<?php $title = 'Admissions requirements'; $lead = 'Review the documents, eligibility criteria and application guidance for SLGTI pathways.'; require APP_PATH . '/Views/partials/page-hero.php'; ?>
<section class="section"><div class="container">
    <form class="filters" method="get"><input type="search" name="q" value="<?= e($q) ?>" placeholder="Search requirements"><select name="category"><option value="">All categories</option><?php foreach ($categories as $item): ?><option value="<?= e($item['category']) ?>" <?= $category === $item['category'] ? 'selected' : '' ?>><?= e($item['category']) ?></option><?php endforeach; ?></select><button class="btn btn-navy" type="submit">Filter</button></form>
    <div class="programme-grid"><?php foreach ($requirements as $item): ?><article class="programme-card"><?php if ($item['image']): ?><img src="<?= e(media_url($item['image'])) ?>" alt="<?= e($item['requirement']) ?>" loading="lazy" width="640" height="400"><?php endif; ?><div><p class="badge"><?= e($item['category'] ?: 'Admissions') ?></p><h2><?= e($item['requirement']) ?></h2><p><?= e($item['short_description'] ?: excerpt($item['description'], 160)) ?></p><p><?= e($item['programme_title'] ?: ($item['department_name'] ?: 'Institution-wide')) ?></p><a class="btn btn-navy" href="<?= e(url('requirements/' . $item['slug'])) ?>">View requirement</a></div></article><?php endforeach; ?><?php if (!$requirements): ?><p>No requirements match this filter.</p><?php endif; ?></div>
</div></section>
